/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { E, Pow, Sym, add, mul, symbols, varianceProp } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.stats.error_prop", () => {
  it("variance_prop(x + y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(varianceProp(add(x, y)))).toBe('Variance(x) + Variance(y)');
  });
  it("variance_prop(x * y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(varianceProp(mul(x, y)))).toBe('x**2*Variance(y) + y**2*Variance(x)');
  });
  it("variance_prop(exp(2*x))", () => {
    const x = new Sym('x');
    expect(sympyStr(varianceProp(new Pow(E, mul(2, x))))).toBe('4*exp(4*x)*Variance(x)');
  });
});
